inline uint32_t enc(const Arr&a){uint32_t x=0;for(int i=0;i<8;i++)x|=(uint32_t)a[i]<<(4*i);return x;} inline Arr dec(uint32_t x){Arr a{};for(int i=0;i<8;i++)a[i]=(x>>(4*i))&15;return a;} inline int total(const Arr&a){int s=0;for(auto x:a)s+=x;return s;} inline bool lexle(const Arr&a,const Arr&b){for(int i=0;i<8;i++){if(a[i]<b[i])return true;if(a[i]>b[i])return false;}return true;} inline double lse2(double a,double b){if(!isfinite(a))return b;if(!isfinite(b))return a;double m=max(a,b);return m+log(exp(a-m)+exp(b-m));}
unordered_map<uint32_t,uint32_t> CC; unordered_map<uint32_t,double> NC; unordered_map<uint64_t,double> M; double alpha0;
uint32_t canon(uint32_t x){auto it=CC.find(x);if(it!=CC.end())return it->second;Arr a=dec(x),t{};uint32_t best=UINT32_MAX;for(int g=0;g<8;g++){t.fill(0);for(int i=0;i<8;i++)t[P[g][i]]=a[i];best=min(best,enc(t));}CC.emplace(x,best);return best;}
double normc(uint32_t x){auto it=NC.find(x);if(it!=NC.end())return it->second;Arr a=dec(x);double t[7]={0};for(int i=0;i<8;i++)for(int d=0;d<7;d++)t[d]+=a[i]*V[i][d];double s=0;for(double z:t)s+=z*z;NC.emplace(x,s);return s;}
inline uint64_t key(uint32_t c,int q){return ((uint64_t)q<<32)|c;} double logZ(uint32_t cs,int q);
struct Tr{uint32_t a,b;double de,logw,logprod,logdiag;bool eq;}; unordered_map<uint64_t,vector<Tr>> TM;
void rec_enum(const Arr&c,int idx,int rem,Arr&a,int m,int q,double beta,double nc,vector<Tr>&trs,double &acc){if(idx==8){if(rem)return;Arr b{};for(int i=0;i<8;i++)b[i]=c[i]-a[i];if(!lexle(a,b))return;uint32_t ra=enc(a),rb=enc(b);double de=(2*normc(ra)+2*normc(rb)-nc)/m;double la=logZ(canon(ra),q);Tr tr{ra,rb,de,0,0,0,a==b};if(a!=b){double lb=logZ(canon(rb),q);tr.logw=-beta*de+la+lb;}else{double l2=logZ(canon(ra),q*2);tr.logprod=2*la;tr.logdiag=l2;tr.logw=-beta*de+lse2(tr.logprod,tr.logdiag)-log(2.0);}acc=lse2(acc,tr.logw);trs.push_back(tr);return;}int tail=0;for(int i=idx+1;i<8;i++)tail+=c[i];for(int x=max(0,rem-tail);x<=min((int)c[idx],rem);x++){a[idx]=x;rec_enum(c,idx+1,rem-x,a,m,q,beta,nc,trs,acc);}a[idx]=0;}
double logZ(uint32_t cs,int q){uint64_t K=key(cs,q);auto it=M.find(K);if(it!=M.end())return it->second;Arr c=dec(cs);int m=total(c);if(m==1){M[K]=0;return 0;}double beta=8.0*alpha0*q/m,nc=normc(cs),acc=-INFINITY;Arr a{};vector<Tr> tmp;rec_enum(c,0,m/2,a,m,q,beta,nc,tmp,acc);M[K]=acc;TM.emplace(K,move(tmp));return acc;}
mt19937_64 rng(20260925); uniform_real_distribution<double> U(0.0,1.0);
double sampleE(uint32_t cs,int q){Arr c=dec(cs);int m=total(c);if(m==1)return 0.;uint64_t K=key(cs,q);double lz=logZ(cs,q);auto &trs=TM.at(K);double r=U(rng),cum=0;Tr const*sel=&trs.back();for(auto const&tr:trs){cum+=exp(tr.logw-lz);if(r<=cum){sel=&tr;break;}}double ea,eb;if(!sel->eq){ea=sampleE(canon(sel->a),q);eb=sampleE(canon(sel->b),q);}else{double lp=sel->logprod,ld=sel->logdiag;double p=1.0/(1.0+exp(ld-lp));if(U(rng)<p){ea=sampleE(canon(sel->a),q);eb=sampleE(canon(sel->a),q);}else{ea=sampleE(canon(sel->a),q*2);eb=ea;}}return sel->de+2.0*(ea+eb);}
int main(int argc,char**argv){int n=argc>1?stoi(argv[1]):4;alpha0=argc>2?stod(argv[2]):0.745;int ns=argc>3?stoi(argv[3]):50000;Arr root{};root.fill(n);uint32_t cs=canon(enc(root));double lz=logZ(cs,1);cerr<<"logZ "<<setprecision(17)<<lz<<" states "<<M.size()<<" transitionsets "<<TM.size()<<"\n";for(int i=0;i<ns;i++)cout<<setprecision(17)<<sampleE(cs,1)<<"\n";}
